package ec.edu.unl.sec.selfassessment.api;
import ec.edu.unl.sec.selfassessment.application.*;import ec.edu.unl.sec.selfassessment.domain.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.net.*;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping public class SelfAssessmentController{private final SelfAssessmentService service;private final ProcessTransitionService transitions;public SelfAssessmentController(SelfAssessmentService service,ProcessTransitionService transitions){this.service=service;this.transitions=transitions;}@GetMapping("/processes")public List<SelfAssessmentProcess> list(){return service.list();}@PostMapping("/processes")public ResponseEntity<SelfAssessmentProcess> create(@Valid @RequestBody ProcessCommand b,HttpServletRequest r){var p=service.create(b.careerId(),b.code(),b.name(),b.periodStart(),b.periodEnd(),b.modelVersionId(),correlation(r));return ResponseEntity.created(URI.create("/api/v1/processes/"+p.id())).eTag(tag(p)).body(p);}@GetMapping("/processes/{id}")public ResponseEntity<SelfAssessmentProcess> get(@PathVariable UUID id){var p=service.get(id);return ResponseEntity.ok().eTag(tag(p)).body(p);}@PostMapping("/processes/{id}/activate")public ResponseEntity<SelfAssessmentProcess> activate(@PathVariable UUID id,@RequestHeader("If-Match")String match,HttpServletRequest r){var p=service.activate(id,rev(match),correlation(r));return ResponseEntity.ok().eTag(tag(p)).body(p);}@PostMapping("/processes/{id}/transitions")public ResponseEntity<SelfAssessmentProcess> transition(@PathVariable UUID id,@RequestHeader("If-Match")String match,@RequestBody TransitionCommand b,HttpServletRequest r){var p=transitions.transition(id,rev(match),b.target(),b.reason(),correlation(r));return ResponseEntity.ok().eTag(tag(p)).body(p);}@PostMapping("/processes/{id}/reopen")public ResponseEntity<SelfAssessmentProcess> reopen(@PathVariable UUID id,@RequestHeader("If-Match")String match,@Valid @RequestBody ReopenCommand b,HttpServletRequest r){var p=transitions.transition(id,rev(match),ProcessState.REOPENED,b.reason(),correlation(r));return ResponseEntity.ok().eTag(tag(p)).body(p);}static long rev(String s){try{return Long.parseLong(s.replace("\"","").strip());}catch(Exception e){throw new IllegalArgumentException("If-Match inválido");}}static String tag(SelfAssessmentProcess p){return "\""+p.revision()+"\"";}static UUID correlation(HttpServletRequest r){Object o=r.getAttribute("sec.correlationId");try{return UUID.fromString(String.valueOf(o));}catch(Exception e){return UUID.randomUUID();}}public record ProcessCommand(@NotNull UUID careerId,@NotBlank @Size(max=100)String code,@NotBlank @Size(max=300)String name,@NotNull LocalDate periodStart,@NotNull LocalDate periodEnd,@NotNull UUID modelVersionId){}public record TransitionCommand(@NotNull ProcessState target,String reason){}public record ReopenCommand(@NotBlank String reason){}}
